import java.io.*; import java.util.*; import java.util.stream.*; import static java.util.stream.Collectors.joining; import static java.util.stream.Collectors.toList; class Result { public static List<Integer> bfs(int n, int m, List<List<Integer>> edges, int s) { List<List<Integer>> adj = new ArrayList<>(n + 1); for (int i = 0; i <= n; i++) { adj.add(new ArrayList<Integer>()); } for (List<Integer> edge : edges) { int u = edge.get(0); int v = edge.get(1); adj.get(u).add(v); adj.get(v).add(u); } int[] dist = new int[n + 1]; Arrays.fill(dist, -1); Queue<Integer> queue = new LinkedList<Integer>(); dist[s] = 0; queue.add(s); while (!queue.isEmpty()) { int u = queue.poll(); for (int v : adj.get(u)) { if (dist[v] == -1) { dist[v] = dist[u] + 6; queue.add(v); } } } List<Integer> result = new ArrayList<Integer>(); for (int i = 1; i <= n; i++) { if (i != s) { result.add(dist[i]); } } return result; } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); BufferedWriter bufferedWriter = new BufferedWriter(new OutputStreamWriter(System.out)); String line = bufferedReader.readLine(); if (line != null) { int q = Integer.parseInt(line.trim()); for (int k = 0; k < q; k++) { String[] firstMultipleInput = bufferedReader.readLine().trim().split(" "); int n = Integer.parseInt(firstMultipleInput[0]); int m = Integer.parseInt(firstMultipleInput[1]); List<List<Integer>> edges = new ArrayList<List<Integer>>(); for (int i = 0; i < m; i++) { String[] edgeInput = bufferedReader.readLine().trim().split(" "); List<Integer> edge = new ArrayList<Integer>(); edge.add(Integer.parseInt(edgeInput[0])); edge.add(Integer.parseInt(edgeInput[1])); edges.add(edge); } int s = Integer.parseInt(bufferedReader.readLine().trim()); List<Integer> result = Result.bfs(n, m, edges, s); StringBuilder sb = new StringBuilder(); for (int i = 0; i < result.size(); i++) { sb.append(result.get(i)); if (i < result.size() - 1) sb.append(" "); } bufferedWriter.write(sb.toString()); bufferedWriter.newLine(); } } bufferedReader.close(); bufferedWriter.close(); } }